(()=>{
  if(window.__ymMotorRuntimeUx20260827)return;window.__ymMotorRuntimeUx20260827=true;
  const AI_API='https://ym-raiox-backend.vercel.app/api/motor/analise-ia';
  const states=new Map();
  const E=v=>window.YM?.esc?YM.esc(v??''):String(v??'').replace(/[&<>"']/g,'');
  const style=document.createElement('style');
  style.id='ymMotorRuntimeUx20260827Styles';
  style.textContent=`
  #vosDataGate.motor-collapsible{padding:0!important;overflow:hidden}
  #vosDataGate.motor-collapsible>.vos-data-head{padding:14px 16px;cursor:pointer;align-items:center}
  #vosDataGate.motor-collapsible .motor-gate-toggle{border:1px solid #cbd8e4;background:#fff;color:#0a2540;border-radius:10px;padding:8px 11px;font:700 12px Inter;cursor:pointer;white-space:nowrap}
  #vosDataGate.motor-collapsible .motor-gate-details{padding:0 16px 16px}
  #vosDataGate.motor-collapsible.motor-collapsed .motor-gate-details{display:none}
  #vosDataGate.motor-collapsible.motor-collapsed>.vos-data-head{border-bottom:0}
  #vosDataGate.motor-collapsible .motor-gate-summary{font-size:12px;color:#607487;margin-top:4px}
  #motorClientContext.motor-collapsible{overflow:hidden}
  #motorClientContext.motor-collapsible>header{cursor:pointer}
  #motorClientContext.motor-collapsible .motor-context-toggle{border:1px solid #cbd8e4;background:#fff;color:#0a2540;border-radius:9px;padding:6px 9px;font:700 11px Inter;cursor:pointer;margin-left:6px}
  #motorClientContext.motor-collapsible.motor-collapsed>.mvc-body{display:none}
  .motor-order-assist{margin:0 0 14px;border:1px solid #cbd9ef;background:linear-gradient(135deg,#f6f9ff,#fff);border-radius:15px;overflow:hidden;box-shadow:0 8px 24px rgba(15,42,67,.06)}
  .motor-order-assist-head{padding:14px 16px;background:#edf3ff;border-bottom:1px solid #d8e4f6;display:flex;justify-content:space-between;gap:12px;align-items:flex-start}
  .motor-order-assist-head b{font:800 15px Montserrat;color:#0a2540}.motor-order-assist-head span{font-size:12px;color:#5d7286;line-height:1.5;display:block;margin-top:4px}
  .motor-order-assist-body{padding:15px 16px}.motor-order-rule{padding:10px 11px;border-radius:10px;background:#f8fafc;border:1px solid #e2e8f0;font-size:13px;line-height:1.55;color:#496176}
  .motor-order-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:11px}.motor-order-actions .ym-btn{min-height:42px}
  .motor-order-manual{margin-top:12px;border-top:1px solid #e4eaf1;padding-top:12px}.motor-order-manual details{background:#fbfdff;border:1px solid #e0e7ef;border-radius:10px;padding:10px 11px}.motor-order-manual summary{font-weight:800;color:#0a2540;cursor:pointer;font-size:13px}
  .motor-order-prompt{margin-top:9px}.motor-order-prompt textarea{min-height:180px;font-size:12.5px;line-height:1.5}
  .motor-order-results{display:grid;gap:10px;margin-top:13px}.motor-order-suggestion{background:#fff;border:1px solid #dbe5ef;border-radius:12px;padding:12px}.motor-order-suggestion h4{font:800 14px Montserrat;color:#0a2540;margin:3px 0 7px}.motor-order-suggestion p{font-size:12.5px;line-height:1.55;color:#425d73;margin:5px 0}.motor-order-basis{margin-top:8px;border-left:4px solid #484dcf;background:#f4f2ff;border-radius:8px;padding:9px 10px}.motor-order-basis b{display:block;font-size:11px;color:#484dcf;margin-bottom:3px}.motor-order-basis span{font-size:12px;line-height:1.5;color:#4d5d74}.motor-order-mini{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:8px}.motor-order-mini>div{padding:8px 9px;border-radius:8px;background:#f8fafc;font-size:11.5px;line-height:1.45;color:#5c7082}.motor-order-imported{margin-top:8px;font-weight:800;color:#238a68;font-size:12px}.motor-order-error{margin-top:10px;border:1px solid #e4bcbc;background:#fff7f7;color:#8a3434;border-radius:10px;padding:10px;font-size:12px}.motor-order-loading{margin-top:10px;border:1px dashed #b7c7dc;background:#f8fbff;color:#50677d;border-radius:10px;padding:10px;font-size:12px}
  @media(max-width:760px){#vosDataGate.motor-collapsible>.vos-data-head{align-items:flex-start}.motor-order-assist-head{flex-direction:column}.motor-order-actions .ym-btn{width:100%}.motor-order-mini{grid-template-columns:1fr}}
  `;
  document.head.appendChild(style);

  function gateApproved(){
    const g=(window.bundle?.gates||[]).find(x=>x.gate_code==='VER_GATE');
    return g?.status==='APROVADO'||['VER_VALIDADO','ORDENAR_PREPARADO','IMPLEMENTACAO'].includes(window.bundle?.case?.status);
  }
  function key(prefix){return `${prefix}:${window.currentId||'none'}`}
  function decorateDataGate(){
    const box=document.getElementById('vosDataGate');if(!box||box.dataset.collapsibleReady==='1')return;
    box.dataset.collapsibleReady='1';box.classList.add('motor-collapsible');
    const head=box.querySelector('.vos-data-head');if(!head)return;
    const details=document.createElement('div');details.className='motor-gate-details';
    [...box.children].filter(x=>x!==head).forEach(x=>details.appendChild(x));box.appendChild(details);
    const ready=window.bundle?.data_readiness?.ready_for_full_vos===true;
    const checks=window.bundle?.data_readiness?.checks||{};const done=Object.values(checks).filter(Boolean).length,total=Object.keys(checks).length||7;
    const title=head.querySelector('div');if(title&&!title.querySelector('.motor-gate-summary'))title.insertAdjacentHTML('beforeend',`<div class="motor-gate-summary">${ready?'Dados já validados · ':''}${done}/${total} verificações atendidas</div>`);
    const btn=document.createElement('button');btn.type='button';btn.className='motor-gate-toggle';btn.textContent='Ver detalhes';head.appendChild(btn);
    const saved=sessionStorage.getItem(key('motorDataGateOpen'));const open=saved==='1'||(!ready&&saved!=='0');
    box.classList.toggle('motor-collapsed',!open);btn.textContent=open?'Minimizar':'Ver detalhes';
    const toggle=()=>{const willOpen=box.classList.contains('motor-collapsed');box.classList.toggle('motor-collapsed',!willOpen);btn.textContent=willOpen?'Minimizar':'Ver detalhes';sessionStorage.setItem(key('motorDataGateOpen'),willOpen?'1':'0')};
    btn.onclick=e=>{e.stopPropagation();toggle()};head.onclick=e=>{if(e.target.closest('button,a,input,select,textarea'))return;toggle()};
  }
  function decorateClientContext(){
    const box=document.getElementById('motorClientContext');if(!box||box.dataset.collapsibleReady==='1')return;
    box.dataset.collapsibleReady='1';box.classList.add('motor-collapsible');const head=box.querySelector('header');if(!head)return;
    const btn=document.createElement('button');btn.type='button';btn.className='motor-context-toggle';btn.textContent='Ver contexto';head.appendChild(btn);
    const ready=window.bundle?.data_readiness?.ready_for_full_vos===true;const saved=sessionStorage.getItem(key('motorContextOpen'));const open=saved==='1'||(!ready&&saved!=='0');box.classList.toggle('motor-collapsed',!open);btn.textContent=open?'Minimizar':'Ver contexto';
    const toggle=()=>{const willOpen=box.classList.contains('motor-collapsed');box.classList.toggle('motor-collapsed',!willOpen);btn.textContent=willOpen?'Minimizar':'Ver contexto';sessionStorage.setItem(key('motorContextOpen'),willOpen?'1':'0')};btn.onclick=e=>{e.stopPropagation();toggle()};head.onclick=e=>{if(e.target.closest('button,a,input,select,textarea'))return;toggle()};
  }
  function compactBundle(){const b=window.bundle||{},c=b.client_context||{};return{case:b.case||{},destination:{short_term:b.case?.destination_short_term||'',success_signal:b.case?.destination_success_signal||''},conclusions:b.conclusions||[],p8_coverage:(b.p8_coverage||[]).map(x=>({p8_code:x.p8_code,p8_label:x.p8_label,classification:x.classification,confidence:x.confidence,observation:x.observation,evidence_summary:x.evidence_summary,remaining_validation:x.remaining_validation,human_status:x.human_status})),evidence:b.evidence||[],ver_entries:b.ver_entries||[],business_metrics:b.business_metrics||[],portfolio_performance:b.portfolio_performance||[],client_context:{onboarding:c.onboarding||null,monthly_history:c.monthly_history||[],performance:c.performance||{}}}}
  function manualPrompt(){return `Você está apoiando a etapa ORDENAR do Método VOS. O diagnóstico VER abaixo JÁ FOI VALIDADO POR UMA PESSOA. Sua função é propor ações candidatas coerentes com o que o VER concluiu.\n\nREGRAS:\n1. Não altere, corrija ou reabra o diagnóstico do VER.\n2. Não invente fatos, números, causas ou evidências.\n3. Gere entre 3 e 7 ações concretas e não redundantes.\n4. Não defina prioridade final, sequência, prazo ou responsável: isso será decisão humana.\n5. Cada ação precisa mostrar claramente qual conclusão/evidência validada do VER a sustenta.\n6. Considere capacidade operacional, dependências e o objetivo do caso quando estiverem disponíveis.\n7. Critério de sucesso deve dizer o que observar depois da execução, sem inventar metas numéricas.\n8. Responda SOMENTE em JSON válido, sem markdown, no formato abaixo.\n\n{\n  "suggestions":[\n    {\n      "id":"S1",\n      "action":"ação concreta",\n      "rationale":"por que responde ao VER",\n      "impact_on_destination":"como pode contribuir para o objetivo",\n      "dependency":"dependência, se houver",\n      "execution_capacity":"cuidado de capacidade, se houver",\n      "risk_of_delay":"o que tende a continuar se for adiada",\n      "digital_front":"frente envolvida, se houver",\n      "success_criterion":"evidência ou KPI a observar",\n      "ver_basis":"conclusão ou evidência humana do VER que originou a sugestão"\n    }\n  ]\n}\n\nCASO VOS:\n${JSON.stringify(compactBundle(),null,2)}`}
  function parseResponse(raw){let s=String(raw||'').trim().replace(/^```json\s*/i,'').replace(/^```\s*/,'').replace(/```$/,'').trim();const a=s.indexOf('{'),z=s.lastIndexOf('}');if(a>=0&&z>a)s=s.slice(a,z+1);const j=JSON.parse(s);const rows=Array.isArray(j?.suggestions)?j.suggestions:[];return rows.slice(0,7).map((x,i)=>({id:String(x.id||`S${i+1}`),action:String(x.action||'').trim(),rationale:String(x.rationale||'').trim(),impact_on_destination:String(x.impact_on_destination||'').trim(),dependency:String(x.dependency||'').trim(),execution_capacity:String(x.execution_capacity||'').trim(),risk_of_delay:String(x.risk_of_delay||'').trim(),digital_front:String(x.digital_front||'').trim(),success_criterion:String(x.success_criterion||'').trim(),ver_basis:String(x.ver_basis||'').trim()})).filter(x=>x.action&&x.rationale&&x.ver_basis)}
  function suggestionHtml(s,st){const imported=!!st.imported?.[s.id];return `<div class="motor-order-suggestion"><div class="ym-meta">SUGESTÃO DA IA · AGUARDA DECISÃO HUMANA</div><h4>${E(s.action)}</h4><p><b>Por que pode ajudar:</b> ${E(s.rationale)}</p><p><b>Impacto esperado:</b> ${E(s.impact_on_destination||'—')}</p><div class="motor-order-basis"><b>BASE NO VER VALIDADO</b><span>${E(s.ver_basis)}</span></div><div class="motor-order-mini"><div><b>Dependência:</b><br>${E(s.dependency||'Nenhuma específica indicada.')}</div><div><b>Critério de sucesso:</b><br>${E(s.success_criterion||'Definir na validação humana.')}</div>${s.execution_capacity?`<div><b>Capacidade:</b><br>${E(s.execution_capacity)}</div>`:''}${s.risk_of_delay?`<div><b>Risco de adiar:</b><br>${E(s.risk_of_delay)}</div>`:''}</div>${imported?'<div class="motor-order-imported">✓ Já enviada para validação humana</div>':`<div class="motor-order-actions"><button class="ym-btn ok" data-accept-ai="${E(s.id)}">Levar para validação</button><button class="ym-btn secondary" data-accept-later="${E(s.id)}">Guardar como não agora</button></div>`}</div>`}
  function orderPanelHtml(st){return `<div class="motor-order-assist" data-runtime-order-ai><div class="motor-order-assist-head"><div><b>IA → sugestões de ação</b><span>O VER já foi validado. A IA propõe ações; você decide o que entra, a ordem, os prazos e responsáveis.</span></div><span>${E(st.model||'Humano no comando')}</span></div><div class="motor-order-assist-body"><div class="motor-order-rule"><b>Regra:</b> nenhuma sugestão vira plano automaticamente. Ela só entra no ORDENAR quando você aceitar.</div><div class="motor-order-actions"><button class="ym-btn" data-order-auto ${st.loading?'disabled':''}>${st.loading?'Analisando…':'Análise automática'}</button><button class="ym-btn secondary" data-order-manual>Usar prompt manual</button></div><div class="motor-order-manual"><details ${st.manualOpen?'open':''}><summary>Fluxo manual sem API</summary><div class="motor-order-prompt"><label class="ym-label">1. Copie este prompt e use no ChatGPT</label><textarea class="ym-textarea" data-order-prompt readonly>${E(manualPrompt())}</textarea><div class="motor-order-actions"><button class="ym-btn secondary" data-copy-order-prompt>Copiar prompt</button></div><label class="ym-label" style="margin-top:10px">2. Cole abaixo a resposta completa da IA</label><textarea class="ym-textarea" data-order-pasted placeholder="Cole aqui o JSON retornado pela IA.">${E(st.pasted||'')}</textarea><div class="motor-order-actions"><button class="ym-btn" data-read-order-response>Ler sugestões coladas</button></div></div></details></div>${st.loading?'<div class="motor-order-loading">A IA está lendo o VER validado e montando sugestões candidatas…</div>':''}${st.error?`<div class="motor-order-error">${E(st.error)}</div>`:''}${st.suggestions?.length?`<div class="motor-order-results">${st.suggestions.map(s=>suggestionHtml(s,st)).join('')}</div>`:''}</div></div>`}
  async function automatic(){const st=states.get(window.currentId)||{};st.loading=true;st.error='';states.set(window.currentId,st);decorateOrder(true);try{const s=await YM.requireSession('/MOTOR'+location.search);if(!s)throw new Error('Sessão necessária');const r=await fetch(AI_API,{method:'POST',headers:{Authorization:'Bearer '+s.access_token,'Content-Type':'application/json'},body:JSON.stringify({case_id:window.currentId,mode:'ORDENAR'})});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'Falha na análise automática');st.suggestions=j.suggestions||[];st.model=j.model||'IA';st.loading=false;states.set(window.currentId,st);decorateOrder(true)}catch(e){st.loading=false;st.error=e.message||String(e);states.set(window.currentId,st);decorateOrder(true)}}
  async function accept(id,notNow){const st=states.get(window.currentId)||{},s=(st.suggestions||[]).find(x=>String(x.id)===String(id));if(!s)return;try{await authFetch('motor-order-actions','POST',{case_id:window.currentId,action:'CREATE_CANDIDATE',candidate_action:s.action,rationale:`${s.rationale}${s.ver_basis?`\n\nBase no VER validado: ${s.ver_basis}`:''}`,impact_on_destination:s.impact_on_destination||'',dependency:s.dependency||'',execution_capacity:s.execution_capacity||'',risk_of_delay:s.risk_of_delay||'',digital_front:s.digital_front||'',success_criterion:s.success_criterion||'',not_now:!!notNow});st.imported=st.imported||{};st.imported[s.id]=true;states.set(window.currentId,st);YM.toast(notNow?'Sugestão guardada como “não agora”.':'Sugestão levada para validação humana.');await openCase(window.currentId);await loadDashboard()}catch(e){YM.toast(e.message||String(e),true)}}
  function bindPanel(panel,st){panel.querySelector('[data-order-auto]')?.addEventListener('click',automatic);panel.querySelector('[data-order-manual]')?.addEventListener('click',()=>{st.manualOpen=true;states.set(window.currentId,st);panel.querySelector('details')?.setAttribute('open','')});panel.querySelector('[data-copy-order-prompt]')?.addEventListener('click',async()=>{const t=panel.querySelector('[data-order-prompt]')?.value||'';try{await navigator.clipboard.writeText(t);YM.toast('Prompt do ORDENAR copiado.')}catch{YM.toast('Não foi possível copiar automaticamente.',true)}});panel.querySelector('[data-read-order-response]')?.addEventListener('click',()=>{try{const raw=panel.querySelector('[data-order-pasted]')?.value||'';const suggestions=parseResponse(raw);if(!suggestions.length)throw new Error('Nenhuma sugestão válida encontrada.');st.pasted=raw;st.suggestions=suggestions;st.error='';st.model='Resposta manual';states.set(window.currentId,st);decorateOrder(true);YM.toast(`${suggestions.length} sugestão(ões) carregada(s). Agora valide humanamente.`)}catch(e){st.error='Não consegui ler a resposta. Peça à IA para devolver somente o JSON no formato do prompt.';states.set(window.currentId,st);decorateOrder(true)}});panel.querySelectorAll('[data-accept-ai]').forEach(b=>b.addEventListener('click',()=>accept(b.dataset.acceptAi,false)));panel.querySelectorAll('[data-accept-later]').forEach(b=>b.addEventListener('click',()=>accept(b.dataset.acceptLater,true)))}
  function decorateOrder(force=false){if(!window.bundle||!window.currentId||!gateApproved())return;const body=document.querySelector('.sec-order > .body')||[...document.querySelectorAll('.motor-section .body')].find(x=>x.closest('.motor-section')?.textContent?.includes('Agora sim: o que deve acontecer primeiro?'));if(!body)return;const existing=body.querySelector('[data-runtime-order-ai]');if(existing&&!force)return;existing?.remove();const st=states.get(window.currentId)||{};body.insertAdjacentHTML('afterbegin',orderPanelHtml(st));bindPanel(body.querySelector('[data-runtime-order-ai]'),st)}
  function run(){decorateDataGate();decorateClientContext();decorateOrder()}
  const obs=new MutationObserver(()=>{clearTimeout(window.__ymMotorUxTimer);window.__ymMotorUxTimer=setTimeout(run,80)});obs.observe(document.documentElement,{childList:true,subtree:true});
  setInterval(run,1200);setTimeout(run,150);
})();
